50	    /// [`items`](Self::items) and [`kv_items`](Self::kv_items) add. A response that never gets a section, budget or
51	    /// provenance renders `name: []` and `totalCount: 0`, the definitive empty list.
52	    pub fn new(type_name: impl Into<String>) -> Self {
53	        Self {
54	            name: type_name.into(),
55	            max_cell_len: DEFAULT_TRUNCATE_CELLS,
56	            truncation_hint: None,
57	            sections: Vec::new(),
58	            budget: None,
59	            provenance: None,
60	            hints: Vec::new(),
61	            recovery: Vec::new(),
62	            is_error: false,
63	            human_content: None,
