67	    /// Append a TOON list section named for the response's type: shorthand for
68	    /// `section(Section::toon(name, fields, rows))`. Every call adds a section, rendered in call order.
69	    ///
70	    /// Sections are root keys, and this shorthand gives each the same name, so for one list per response only: a
71	    /// second `items()` call repeats the key `name`, and the response renders the `toon_validation_failed` error
72	    /// naming it (and `is_error()` is true) instead of invalid TOON. Mixing with [`kv_items`](Self::kv_items) works
73	    /// while no KV key equals the type name. For several lists, give each its own name with
74	    /// `.section(Section::toon(distinct_name, ..))`. To report a total, build the section yourself and set
75	    /// [`Section::total_count`].
76	    #[must_use]
77	    pub fn items(self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
78	        let name = self.name.clone();
79	        self.section(Section::toon(name, fields.iter().map(|s| (*s).to_string()).collect(), rows))
80	    }
