82	    /// Append a TOON list section for a cut list, in one call. The rows are `outcome.kept`, each turned into a row by
83	    /// `row`; the section's total is `outcome.total_before`; and, only when something was cut,
84	    /// [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint) (`showing {kept} of {total}; {guidance}`)
85	    /// is appended to the hints. michi builds the rows from the outcome itself, so the list's `[N]`, its `totalCount`
86	    /// and the `help[]` line all describe the same cut.
87	    ///
88	    /// `totalCount` renders only when `total_before` exceeds the rows kept.
89	    ///
90	    /// ```
91	    /// use michi_core::toon::Value;
92	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat};
93	    ///
94	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
95	    /// let r = AgentResponse::new("issues").truncated_section(
96	    ///     "issues",
97	    ///     vec!["n".into()],
98	    ///     &outcome,
99	    ///     |n| vec![Value::Int(*n)],
100	    ///     "pass --limit 4",
101	    /// );
102	    /// assert_eq!(
103	    ///     r.render(OutputFormat::Text),
104	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
105	    /// );
106	    /// ```
107	    #[must_use]
108	    pub fn truncated_section<T>(
109	        mut self,
110	        name: impl Into<String>,
111	        fields: Vec<String>,
112	        outcome: &crate::truncation::TruncationOutcome<T>,
113	        row: impl FnMut(&T) -> Vec<Value>,
114	        guidance: impl Into<String>,
115	    ) -> Self {
116	        let rows = outcome.kept.iter().map(row).collect();
117	        if let Some(hint) = outcome.hint(guidance) {
118	            self.hints.push(hint);
119	        }
120	        self.section(Section::toon(name, fields, rows).total_count(Some(outcome.total_before)))
121	    }
122	
123	    /// Append a KV section named for the response's type: shorthand for `section(Section::kv(name, items))`. The name
124	    /// is not printed for a KV body. Every call adds a section, but the item keys are root keys: two calls sharing a
125	    /// key render the `toon_validation_failed` error naming it. See [`items`](Self::items); for several KV sections
126	    /// use `.section(Section::kv(name, ..))` and keep the keys distinct.
127	    #[must_use]
128	    pub fn kv_items(self, items: Vec<KvItem>) -> Self {
129	        let name = self.name.clone();
130	        self.section(Section::kv(name, items))
131	    }
132	
133	    /// Append a section. Sections render in call order, the one place a response keeps its body: the caller owns
134	    /// ordering.
135	    ///
136	    /// The response's cell cap ([`truncate_cells_at`](Self::truncate_cells_at)) and truncation hint apply to every
137	    /// `Toon` body. A section's `totalCount` comes from [`Section::total_count`]. Each section is a root key of the
138	    /// document, so names must be distinct (see [`Section`]).
139	    #[must_use]
140	    pub fn section(mut self, section: Section) -> Self {
141	        self.sections.push(section);
142	        self
143	    }
144	
145	    /// Attach the response-level budget report; one per response, a second call replaces the first. It renders as a
146	    /// `budget:` block after the last section (see [`BudgetSummary`] for what it carries), and the per-section
147	    /// roll-up appears only when the response has two or more sections. michi renders the report; it never computes
148	    /// it.
