166	    /// Append a contextual hint.
167	    #[must_use]
168	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
169	        self.hints.push(Hint::new(hint));
170	        self
171	    }
172	
173	    /// Replace all contextual hints.
174	    #[must_use]
175	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
176	        self.hints = hints;
177	        self
178	    }
