197	        self.max_cell_len = limit;
198	        self
199	    }
200	
201	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
202	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction. At most
203	    /// [`crate::toon::MAX_TRUNCATION_HINT_CHARS`] chars: a longer hint renders the `toon_validation_failed` error.
204	    /// Unset by default: michi never invents a parameter the tool may not have, and the `truncated` block still
205	    /// reports each cut. Pass tool-author text, never data.
206	    #[must_use]
207	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
208	        self.truncation_hint = Some(hint.into());
209	        self
210	    }
211	
212	    /// Mark this response as an error state.
213	    #[must_use]
214	    pub fn as_error(mut self) -> Self {
215	        self.is_error = true;
216	        self
217	    }
218	
219	    /// Attach a human-facing companion block (`audience: user`).
220	    #[must_use]
221	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
222	        self.human_content = Some(text.into());
223	        self
224	    }
225	
226	    /// The caller's hints, then michi's own truncation line when there is one: a single `help` block.
227	    fn hints_with<'a>(&'a self, extra: &[Hint]) -> std::borrow::Cow<'a, [Hint]> {
228	        if extra.is_empty() {
229	            std::borrow::Cow::Borrowed(&self.hints)
230	        } else {
231	            let mut all = Vec::with_capacity(self.hints.len() + extra.len());
232	            all.extend(self.hints.iter().cloned());
233	            all.extend(extra.iter().cloned());
234	            std::borrow::Cow::Owned(all)
235	        }
236	    }
237	
238	    /// The list a `Toon` section renders: borrowed from the section, with the response's cell cap and truncation hint.
239	    /// Nothing is copied, so validating and rendering cost what the output costs, not a second copy of the rows.
240	    fn list_ref<'a>(&'a self, name: &'a str, fields: &'a [String], rows: &'a [Vec<Value>]) -> ListRef<'a> {
241	        ListRef {
242	            type_name: name,
243	            fields,
244	            rows,
245	            max_cell_len: self.max_cell_len,
246	            truncation_hint: self.truncation_hint.as_deref(),
247	        }
248	    }
249	
250	    /// The blocks to render: the sections, or, for a response with nothing at all, the one empty list that names
251	    /// its type. A budget or provenance block stands alone, with no empty list before it.
252	    fn blocks(&self) -> std::borrow::Cow<'_, [Section]> {
253	        if self.sections.is_empty() && self.budget.is_none() && self.provenance.is_none() {
254	            std::borrow::Cow::Owned(vec![Section::toon(self.name.as_str(), Vec::new(), Vec::new())])
255	        } else {
256	            std::borrow::Cow::Borrowed(&self.sections)
257	        }
258	    }
259	
260	    /// One section as an envelope part.
261	    fn section_part<'a>(&self, s: &'a Section) -> (Part<'a>, bool, Option<Hint>) {
262	        let total = s.shown_total();
263	        let name = s.name();
264	        match s.body() {
265	            SectionBody::Toon { fields, rows } => {
266	                match ToonDocument::validate_list(self.list_ref(name, fields, rows)) {
267	                    Ok(doc) => {
268	                        // An empty list is the definitive empty state: `name: []` and `totalCount: 0`, so a reader sees
269	                        // "zero results" and not a list that might have been dropped. A larger total the caller set
270	                        // (everything was cut) stays as it is.
271	                        let total = total.or_else(|| rows.is_empty().then_some(0));
272	                        let list = doc.render_list();
273	                        let cuts = list
274	                            .cuts
275	                            .iter()
276	                            .map(|&(row, field, removed)| crate::toon::table::Cut {
277	                                section: name,
278	                                row,
279	                                field: fields.get(field).map_or("", String::as_str),
280	                                removed,
281	                            })
282	                            .collect();
283	                        (Part { name, text: list.text, cuts, total }, false, list.extra_hint.map(Hint::new))
284	                    }
285	                    Err(e) => (Part::failed(name, "toon_validation_failed", &e.to_string()), true, None),
286	                }
287	            }
288	            SectionBody::Kv(items) => kv_part(name, items, total),
289	            // One string value under the section's name, escaped like any other value: prose cannot start a line
290	            // of its own, so it cannot forge a `help[]` line or break the document.
291	            SectionBody::Text { text, .. } => {
292	                let line = format!("{}: {}", crate::toon::escape_key(name), crate::toon::escape_value(text));
293	                (Part { name, text: line, cuts: Vec::new(), total }, false, None)
294	            }
295	        }
296	    }
297	
298	    /// Whether each block fails validation, without rendering it.
299	    fn failed_flags(&self) -> Vec<bool> {
300	        self.blocks()
301	            .iter()
302	            .map(|s| match s.body() {
303	                SectionBody::Toon { fields, rows } => {
304	                    ToonDocument::validate_list(self.list_ref(s.name(), fields, rows)).is_err()
305	                }
306	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
307	                SectionBody::Text { .. } => false,
308	            })
309	            .collect()
310	    }
311	
312	    /// The first key the body cannot render, or `None`. Sections render as root keys (a TOON list or text section
313	    /// under its name, a KV section as its item keys), beside the keys michi writes itself
314	    /// ([`crate::toon::RESERVED_ROOT_KEYS`]: the envelope blocks, the keys that follow a body, and the error
315	    /// document's keys). The reserved names are claimed whether or not michi writes that block here, so validity
316	    /// never depends on the caller's data, and a success response cannot carry `error:` or `message:` lines.
317	    /// `failed[i]` says whether block `i` failed validation: its `error` and `message` lines are michi's own, so a
318	    /// second failed block is a collision on `error`. Provenance labels sit one level down (see
319	    /// [`crate::provenance::label_collision`]).
320	    fn root_collision(&self, failed: &[bool]) -> Option<String> {
321	        let blocks = self.blocks();
322	        let mut seen: std::collections::HashSet<&str> = crate::toon::RESERVED_ROOT_KEYS.into_iter().collect();
323	        let mut error_block = false;
324	        for (s, failed) in blocks.iter().zip(failed) {
325	            if *failed {
326	                if error_block {
327	                    return Some("error".to_string());
328	                }
329	                error_block = true;
330	                continue;
331	            }
332	            let keys: Vec<&str> = match s.body() {
333	                SectionBody::Toon { .. } | SectionBody::Text { .. } => vec![s.name()],
334	                SectionBody::Kv(items) => items.iter().map(|i| i.key.as_str()).collect(),
335	            };
336	            for key in keys {
337	                if !seen.insert(key) {
338	                    return Some(key.to_string());
339	                }
340	            }
341	        }
342	        let p = self.provenance.as_ref()?;
343	        crate::provenance::label_collision(p).map(str::to_string)
344	    }
345	
346	    /// The body: sections, `budget:`, `provenance:`.
347	    ///
348	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
349	    /// may appear once: when one block has them they stay inline after its list; when two or more do, each becomes
350	    /// one table with a leading `section` column, after the last block.
351	    ///
352	    /// The flag is whether this response is an error: set by `as_error()` or by a block that failed validation.
353	    /// Every output surface reads its error flag from here so text, JSON and MCP never disagree.
354	    fn body(&self) -> (String, bool, Vec<Hint>) {
355	        let blocks = self.blocks();
356	        let mut parts: Vec<Part<'_>> = Vec::with_capacity(blocks.len());
357	        let mut failed = false;
358	        let mut flags: Vec<bool> = Vec::with_capacity(blocks.len());
359	        let mut extras: Vec<Hint> = Vec::new();
360	        for s in blocks.iter() {
361	            let (part, part_failed, extra) = self.section_part(s);
362	            failed |= part_failed;
363	            flags.push(part_failed);
364	            // One line per cut response is enough: every section's line says the same thing.
365	            if let Some(h) = extra {
366	                if !extras.contains(&h) {
367	                    extras.push(h);
368	                }
369	            }
370	            parts.push(part);
371	        }
372	        // Two blocks writing one root key would be invalid TOON. Like any other bad input the whole body becomes the
373	        // visible validation error, so the caller sees it instead of a document a decoder rejects.
374	        if let Some(key) = self.root_collision(&flags) {
375	            return (collision_body(&key), true, Vec::new());
376	        }
377	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
378	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
379	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
380	        for p in &parts {
381	            join_block(&mut out, &p.text);
382	            if cutters == 1 {
383	                crate::toon::table::push_truncated(&mut out, &p.cuts, false);
384	            }
385	            if let (1, Some(n)) = (totals, p.total) {
386	                join_block(&mut out, &format!("totalCount: {n}"));
387	            }
388	        }
389	        if cutters >= 2 {
390	            let cuts: Vec<crate::toon::table::Cut<'_>> = parts.iter().flat_map(|p| p.cuts.iter().cloned()).collect();
391	            crate::toon::table::push_truncated(&mut out, &cuts, true);
392	        }
393	        if totals >= 2 {
394	            use crate::toon::table::{self, Cell};
395	            table::push_header(&mut out, "totalCount", totals, ["section", "total"]);
396	            for p in &parts {
397	                if let Some(total) = p.total {
398	                    table::push_row(&mut out, &[Cell::Str(p.name), Cell::count(total)]);
399	                }
400	            }
401	        }
402	        if let Some(b) = &self.budget {
403	            join_block(&mut out, &crate::budget::render_budget_block(b, &self.sections));
404	        }
405	        if let Some(p) = &self.provenance {
406	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
407	        }
408	        (out, failed || self.is_error, extras)
409	    }
410	
411	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
412	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
413	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
414	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
415	        let hints = self.hints_with(extra);
416	        if !hints.is_empty() || !self.recovery.is_empty() {
417	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
418	        }
419	        crate::hints::append_hints(&mut body, &hints);
420	        crate::recovery::append_recovery(&mut body, &self.recovery);
421	        body
422	    }
423	
424	    /// Render the response in the requested format.
425	    #[must_use]
426	    pub fn render(&self, format: OutputFormat) -> String {
427	        match format {
428	            OutputFormat::Text => self.render_text(),
429	            OutputFormat::Json => self.render_json(),
430	        }
431	    }
432	
433	    fn render_text(&self) -> String {
434	        let (body, _, extra) = self.body();
435	        self.finish_text(body, &extra)
436	    }
437	
438	    /// Whether this response is an error: `as_error()` was called, or a section's TOON rows or KV items failed
439	    /// validation and its block is a `toon_validation_failed` or `kv_validation_failed` error block. Validates
440	    /// without rendering.
441	    #[must_use]
442	    pub fn is_error(&self) -> bool {
443	        if self.is_error {
444	            return true;
445	        }
446	        let failed = self.failed_flags();
447	        failed.contains(&true) || self.root_collision(&failed).is_some()
448	    }
449	
450	    /// Render just the `help[N]:` block for `self.hints`.
451	    #[must_use]
452	    pub fn render_hints_only(&self) -> String {
453	        crate::hints::render_hints(&self.hints)
454	    }
455	
456	    /// Render for the given audience.
457	    #[must_use]
458	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
459	        match audience {
460	            crate::audience::Audience::Assistant => self.render_text(),
461	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
462	        }
463	    }
464	
465	    /// Whether `.human_content()` was set on this builder.
466	    #[must_use]
467	    pub fn has_human_content(&self) -> bool {
468	        self.human_content.is_some()
469	    }
470	
471	    /// Build the MCP `CallToolResult` for this response.
472	    #[must_use]
473	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
474	        let (body, is_error, extra) = self.body();
475	        let structured_content = self.json_from_body(&body, is_error, &extra);
476	        let mut content = vec![crate::mcp::ContentBlock {
477	            text: self.finish_text(body, &extra),
478	            audience: vec![crate::audience::Audience::Assistant],
479	        }];
480	        if let Some(human) = &self.human_content {
481	            content.push(crate::mcp::ContentBlock {
482	                text: human.clone(),
483	                audience: vec![crate::audience::Audience::User],
484	            });
485	        }
486	        crate::mcp::CallToolResult::new(
487	            content,
488	            is_error,
489	            Some(crate::mcp::JsonObject::from_trusted(structured_content)),
490	        )
491	    }
492	
493	    fn render_json(&self) -> String {
494	        let (body, is_error, extra) = self.body();
495	        self.json_from_body(&body, is_error, &extra)
496	    }
497	
498	    fn json_from_body(&self, body: &str, is_error: bool, extra: &[Hint]) -> String {
499	        let hints = self.hints_with(extra);
500	        let capacity =
501	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
502	        let mut out = String::with_capacity(capacity + 128);
503	        out.push_str("{\"body\":");
504	        json::push_str(&mut out, body);
505	        if !self.sections.is_empty() {
506	            out.push_str(",\"sections\":");
507	            json::push_array(&mut out, &self.sections, push_section_json);
508	        }
509	        if let Some(b) = &self.budget {
510	            out.push_str(",\"budget\":");
511	            crate::budget::push_budget_json(&mut out, b, &self.sections);
512	        }
513	        if let Some(p) = &self.provenance {
514	            out.push_str(",\"provenance\":");
515	            crate::provenance::push_provenance_json(&mut out, p);
516	        }
517	        out.push_str(",\"hints\":");
518	        json::push_str_array(&mut out, hints.iter().map(Hint::as_str));
519	        out.push_str(",\"recovery\":");
520	        json::push_array(&mut out, &self.recovery, json::push_recovery);
521	        out.push_str(",\"isError\":");
522	        json::push_bool(&mut out, is_error);
523	        out.push('}');
524	        out
525	    }
526	}
527	
528	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
529	fn validation_error_body(code: &str, message: &str) -> String {
530	    let message = crate::toon::escape_value(message);
531	    let mut out = String::with_capacity(17 + code.len() + message.len());
532	    out.push_str("error: ");
533	    out.push_str(code);
534	    out.push_str("\nmessage: ");
535	    out.push_str(&message);
536	    out
537	}
538	
539	/// The body for two blocks that would write the same root key.
540	fn collision_body(key: &str) -> String {
541	    validation_error_body(
542	        "toon_validation_failed",
543	        &format!("duplicate root key '{key}': give every section and KV key a distinct name"),
544	    )
545	}
546	
547	/// One block of an envelope body before the root-level `truncated` and `totalCount` keys are placed.
548	struct Part<'a> {
549	    /// The block's name, the `section` column when several blocks share a root key.
550	    name: &'a str,
551	    /// The block's text without its `truncated` block or `totalCount` line.
552	    text: String,
553	    /// Cut cells, for the `truncated` block.
554	    cuts: Vec<crate::toon::table::Cut<'a>>,
555	    /// The `totalCount` this block reports, when it reports one.
556	    total: Option<usize>,
557	}
558	
559	impl<'a> Part<'a> {
560	    /// A block that failed validation: the error body replaces its content and it reports no count.
561	    fn failed(name: &'a str, code: &str, message: &str) -> Self {
562	        Self { name, text: validation_error_body(code, message), cuts: Vec::new(), total: None }
563	    }
564	}
565	
566	/// A KV block as a part. No items still reports a larger total the caller set.
567	fn kv_part<'a>(name: &'a str, items: &[KvItem], total: Option<usize>) -> (Part<'a>, bool, Option<Hint>) {
568	    if items.is_empty() {
569	        return (Part { name, text: String::new(), cuts: Vec::new(), total }, false, None);
570	    }
571	    match crate::kv::render_kv(items) {
572	        Ok(text) => (Part { name, text, cuts: Vec::new(), total }, false, None),
573	        Err(e) => (Part::failed(name, "kv_validation_failed", &e.to_string()), true, None),
574	    }
575	}
576	
577	/// Append `block` after a LF unless either side is empty.
578	fn join_block(out: &mut String, block: &str) {
579	    if block.is_empty() {
580	        return;
581	    }
582	    if !out.is_empty() {
583	        out.push('\n');
584	    }
585	    out.push_str(block);
586	}
587	
588	/// One section as the JSON object spec 07 section 5 describes. Rows carry the full values: the per-cell cap shapes
589	/// the text render, and `structuredContent` is the typed copy of the same data. `returnedCount` and `truncated` are
590	/// the section's own derived facts, the ones the text render uses.
591	fn push_section_json(out: &mut String, s: &Section) {
592	    out.push_str("{\"name\":");
593	    json::push_str(out, s.name());
594	    match s.body() {
595	        SectionBody::Toon { fields, rows } => {
596	            out.push_str(",\"kind\":\"toon\",\"fields\":");
597	            json::push_str_array(out, fields.iter().map(String::as_str));
598	            out.push_str(",\"rows\":");
599	            json::push_array(out, rows, |out, row| json::push_array(out, row, json::push_value));
600	        }
601	        SectionBody::Kv(items) => {
602	            out.push_str(",\"kind\":\"kv\",\"items\":");
603	            json::push_array(out, items, |out, item| {
604	                out.push_str("{\"key\":");
605	                json::push_str(out, &item.key);
606	                out.push_str(",\"value\":");
607	                json::push_kv_value(out, &item.value);
608	                out.push('}');
609	            });
610	        }
611	        SectionBody::Text { text, .. } => {
612	            out.push_str(",\"kind\":\"text\",\"text\":");
613	            json::push_str(out, text);
614	        }
615	    }
616	    out.push_str(",\"returnedCount\":");
617	    json::push_uint(out, s.count() as u64);
618	    if let Some(total) = s.total() {
619	        out.push_str(",\"totalCount\":");
620	        json::push_uint(out, total as u64);
621	    }
622	    out.push_str(",\"truncated\":");
623	    json::push_bool(out, s.truncated());
624	    out.push('}');
625	}
