629	    use super::*;
630	
631	    #[test]
632	    fn capacity_violations_are_toon_validation_errors_on_every_surface() {
633	        let fields: Vec<String> = (0..=crate::toon::MAX_FIELDS).map(|i| format!("f{i}")).collect();
634	        let field_refs: Vec<&str> = fields.iter().map(String::as_str).collect();
635	        let too_wide = AgentResponse::new("t").items(vec![], &field_refs);
636	        let long_hint = AgentResponse::new("t")
637	            .items(vec![vec![Value::from("x")]], &["a"])
638	            .truncation_hint("h".repeat(crate::toon::MAX_TRUNCATION_HINT_CHARS + 1));
639	        for (r, message) in [
640	            (too_wide, "fields length 1001 exceeds maximum of 1000"),
641	            (long_hint, "truncation_hint length 257 chars exceeds maximum of 256"),
642	        ] {
643	            assert!(r.is_error(), "{message}");
644	            let text = r.render(OutputFormat::Text);
645	            assert_eq!(text, format!("error: toon_validation_failed\nmessage: {message}"));
646	            assert!(r.render(OutputFormat::Json).contains("\"isError\":true"), "{message}");
647	            let result = r.to_call_tool_result();
