134	    /// `Timeout` returns `Ambiguous` (the operation may have taken effect); `RateLimited`, `Unavailable` and
135	    /// `ExternalFailure` return `Internal`; caller-fault codes return `User`. Used by [`DomainError::class`] when the
136	    /// error is not marked retryable.
137	    #[must_use]
138	    pub fn default_class(&self) -> ErrorClass {
139	        match self {
140	            Self::InvalidInput | Self::NotFound | Self::Unauthorized | Self::Forbidden | Self::Conflict => {
141	                ErrorClass::User
142	            }
143	            Self::RateLimited | Self::Unavailable | Self::ExternalFailure => ErrorClass::Internal,
144	            Self::Timeout => ErrorClass::Ambiguous,
145	        }
146	    }
147	}
148	
149	/// The [`label`](ErrorCode::label).
150	impl std::fmt::Display for ErrorCode {
151	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
152	        f.write_str(self.label())
153	    }
154	}
