156	/// A string that is not an [`ErrorCode`] label.
157	#[derive(Debug, Clone, PartialEq, Eq)]
158	pub struct UnknownErrorCode(pub String);
159	
160	impl std::fmt::Display for UnknownErrorCode {
161	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
162	        write!(f, "unknown error code {:?}; expected one of: ", self.0)?;
163	        for (i, code) in ErrorCode::ALL.iter().enumerate() {
164	            f.write_str(if i == 0 { "" } else { ", " })?;
165	            f.write_str(code.label())?;
166	        }
167	        Ok(())
168	    }
169	}
170	
171	impl std::error::Error for UnknownErrorCode {}
172	
173	impl std::str::FromStr for ErrorCode {
