181	
182	/// A domain-level error.
183	///
184	/// `causes` say why it happened (diagnosis); `hints` say what to do next (guidance). They are separate fields, and
185	/// render as separate keys, so an agent can tell them apart. [`DomainError::from_error_with_causes`] fills `message`
186	/// and `causes` from a `std::error::Error` and its `source()` chain.
187	///
188	/// The fields are private: build the error with [`DomainError::new`] and the builder methods, and read it with the
189	/// getters. The builder keeps [`MAY_HAVE_TAKEN_EFFECT_HINT`] in step with the code and the retry flag, which a field
190	/// write would skip (a `Timeout` set retryable after construction kept the "verify first" hint; a `RateLimited` error
191	/// whose code became `Timeout` was retryable with no hint at all).
192	///
193	/// ```compile_fail,E0616
194	/// let mut e = michi_core::DomainError::new(michi_core::ErrorCode::Timeout, "POST /charge timed out");
195	/// e.retryable = true;
196	/// ```
197	///
198	/// ```compile_fail,E0616
199	/// let mut e = michi_core::DomainError::new(michi_core::ErrorCode::RateLimited, "slow down");
200	/// e.code = michi_core::ErrorCode::Timeout;
201	/// ```
202	///
203	/// With the `serde` feature it serializes to exactly the JSON of `render(OutputFormat::Json)`
204	/// (`{isError, error, message, causes, retryable, hints, recovery}`), and with `schemars` its schema describes that
205	/// form, so it can be used as an MCP `outputSchema`. `retry_after` is not part of that form.
206	#[derive(Debug, Clone, PartialEq)]
207	#[cfg_attr(feature = "serde", derive(serde::Serialize))]
208	#[cfg_attr(feature = "serde", serde(into = "DomainErrorWire"))]
209	#[non_exhaustive]
210	pub struct DomainError {
211	    code: ErrorCode,
212	    message: String,
213	    causes: Vec<String>,
214	    hints: Vec<Hint>,
215	    recovery: Option<RecoveryHint>,
216	    retryable: bool,
217	    retry_after: Option<Duration>,
218	}
219	
220	impl DomainError {
221	    /// Create a domain error. The message is tool-author text, never data: michi renders it as the error's own
222	    /// voice, and a value copied from a file, web page or user field can carry instructions. See the trust model in
223	    /// `docs/spec/02-toon-format.md`.
224	    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
225	        let mut err = Self {
226	            retryable: code.is_retryable_by_default(),
227	            code,
228	            message: message.into(),
229	            causes: Vec::new(),
230	            hints: Vec::new(),
231	            recovery: None,
232	            retry_after: None,
233	        };
234	        err.sync_effect_hint();
235	        err
236	    }
237	
238	    /// Keeps [`MAY_HAVE_TAKEN_EFFECT_HINT`] present exactly while the error's code may have taken effect and it is not
239	    /// marked retryable.
240	    fn sync_effect_hint(&mut self) {
241	        let wanted = self.code.may_have_taken_effect() && !self.retryable;
242	        let present = self.hints.iter().any(|h| h.as_str() == MAY_HAVE_TAKEN_EFFECT_HINT);
243	        if wanted && !present {
244	            self.hints.push(Hint::new(MAY_HAVE_TAKEN_EFFECT_HINT));
245	        } else if !wanted && present {
246	            self.hints.retain(|h| h.as_str() != MAY_HAVE_TAKEN_EFFECT_HINT);
247	        }
248	    }
249	
250	    /// Build a domain error from an existing error, keeping only its own `Display` as `message`.
251	    ///
252	    /// The `source()` chain is **not** copied: underlying errors often carry URLs with tokens, file paths and other
253	    /// internals that should not reach an agent. Use [`DomainError::from_error_with_causes`] to opt in to the chain.
254	    /// The top-level `Display` is still agent-visible, so make sure it is safe to show; if it is not, build the
255	    /// error with [`DomainError::new`] and a message you wrote. The message is tool-author text, never data. As a
256	    /// safety net the text goes through [`crate::redact::redact_common_shapes`]: URL userinfo, the values of
257	    /// `token=`/`api_key=`/`password=`-style pairs (a `reqwest` error puts the whole URL, query included, in its
258	    /// top-level `Display`) and a few token prefixes become `[REDACTED]`. That is best effort, not a guarantee: see
259	    /// that function for what it misses.
260	    ///
261	    /// ```
262	    /// use michi_core::{DomainError, ErrorCode};
263	    ///
264	    /// #[derive(Debug, thiserror::Error)]
265	    /// #[error("sync failed")]
266	    /// struct Sync(#[source] std::io::Error);
267	    ///
268	    /// let io = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "/home/ci/.netrc: permission denied");
269	    /// let e = DomainError::from_error(ErrorCode::ExternalFailure, &Sync(io));
270	    /// assert_eq!(e.message(), "sync failed");
271	    /// assert!(e.causes().is_empty());
272	    /// ```
273	    pub fn from_error(code: ErrorCode, err: &(dyn std::error::Error + 'static)) -> Self {
274	        Self::new(code, crate::redact::redact_common_shapes(&err.to_string()))
275	    }
276	
277	    /// Like [`DomainError::from_error`], and also copies the `source()` chain into `causes`. Opt-in: every link's
278	    /// `Display` becomes agent-visible text, so use it only when the whole chain is safe to show (no URLs with
279	    /// tokens, no paths or internals you would not print to an end user). The same redaction is applied to every link, as in
280	    /// [`DomainError::from_error`].
281	    ///
282	    /// Each `source()` link, outermost first, adds its `Display` as one entry of `causes` (never a hint: causes are
283	    /// diagnosis, hints are guidance). A link whose text is already contained in the last text kept (the message, or
284	    /// the previous cause kept) is skipped, because `thiserror` messages often embed their source
285	    /// (`#[error("walk failed: {0}")]`) and would otherwise repeat it. Line breaks stay inside their entry; the
286	    /// renderers escape them. The walk stops after 128 links, so a cyclic `source()` cannot loop.
287	    ///
288	    /// The chain is kept as text only: no source error is stored, so [`std::error::Error::source`] on the result is
289	    /// still `None`, and the result stays `Clone`, `Send` and `Sync`. Add a prefix with
290	    /// [`context`](Self::context).
291	    ///
292	    /// ```
293	    /// use michi_core::{DomainError, ErrorCode};
294	    ///
295	    /// #[derive(Debug, thiserror::Error)]
296	    /// #[error("walk failed: {0}")]
297	    /// struct Walk(#[source] std::io::Error);
298	    ///
299	    /// let io = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "permission denied");
300	    /// let e = DomainError::from_error_with_causes(ErrorCode::ExternalFailure, &Walk(io));
301	    /// assert_eq!(e.message(), "walk failed: permission denied");
302	    /// assert!(e.causes().is_empty(), "the message already holds the only cause");
303	    /// ```
304	    pub fn from_error_with_causes(code: ErrorCode, err: &(dyn std::error::Error + 'static)) -> Self {
305	        let mut out = Self::from_error(code, err);
306	        let mut link = err.source();
307	        for _ in 0..MAX_CAUSE_LINKS {
308	            let Some(e) = link else { break };
309	            let text = crate::redact::redact_common_shapes(&e.to_string());
310	            let previous = out.causes.last().unwrap_or(&out.message);
311	            if !previous.contains(text.as_str()) {
312	                out.causes.push(text);
313	            }
314	            link = e.source();
315	        }
316	        out
317	    }
318	
319	    /// Append one cause (why the error happened), rendered after the message as `causes[N]: …`. Tool-author text,
320	    /// never data, and nothing you would not show an end user (no tokens, internal paths).
321	    #[must_use]
322	    pub fn cause(mut self, cause: impl Into<String>) -> Self {
323	        self.causes.push(cause.into());
324	        self
325	    }
326	
327	    /// Append a contextual hint. Tool-author text, never data.
328	    #[must_use]
329	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
330	        self.hints.push(Hint::new(hint));
331	        self
332	    }
333	
334	    /// Attach a structured recovery hint.
335	    #[must_use]
336	    pub fn recovery(mut self, r: RecoveryHint) -> Self {
337	        self.recovery = Some(r);
338	        self
339	    }
340	
341	    /// Override the default retryability for this error instance. Pass `true` for a `Timeout` or `ExternalFailure`
342	    /// only when repeating the operation is safe (it is idempotent, or known not to have taken effect).
343	    #[must_use]
344	    pub fn retryable(mut self, retryable: bool) -> Self {
345	        self.retryable = retryable;
346	        self.sync_effect_hint();
347	        self
348	    }
349	
350	    /// Attach a `Retry-After` delay, or clear it with `None`.
351	    #[must_use]
352	    pub fn retry_after(mut self, d: impl Into<Option<Duration>>) -> Self {
353	        self.retry_after = d.into();
354	        self
355	    }
356	
357	    /// Prefix the message with `context`, as `"{context}: {message}"`, keeping everything else. Tool-author text, never
358	    /// data.
359	    ///
360	    /// ```
361	    /// use michi_core::{DomainError, ErrorCode};
362	    ///
363	    /// let e = DomainError::new(ErrorCode::NotFound, "no such file").context("load config");
364	    /// assert_eq!(e.message(), "load config: no such file");
365	    /// ```
366	    #[must_use]
367	    pub fn context(mut self, context: impl std::fmt::Display) -> Self {
368	        self.message = format!("{context}: {}", self.message);
369	        self
370	    }
371	
372	    /// The error's code.
373	    #[must_use]
374	    pub fn code(&self) -> ErrorCode {
375	        self.code
376	    }
377	
378	    /// The human-readable message.
379	    #[must_use]
380	    pub fn message(&self) -> &str {
381	        &self.message
382	    }
383	
384	    /// Why it happened, outermost first: one entry per underlying cause, rendered as `causes[N]: …` after the message.
385	    #[must_use]
386	    pub fn causes(&self) -> &[String] {
387	        &self.causes
388	    }
389	
390	    /// The contextual hints, rendered as `help[N]: …`, including [`MAY_HAVE_TAKEN_EFFECT_HINT`] while it applies.
391	    #[must_use]
392	    pub fn hints(&self) -> &[Hint] {
393	        &self.hints
394	    }
395	
396	    /// The structured recovery hint, if one was attached with [`recovery`](Self::recovery).
397	    #[must_use]
398	    pub fn get_recovery(&self) -> Option<&RecoveryHint> {
399	        self.recovery.as_ref()
400	    }
401	
402	    /// The `Retry-After` delay attached with [`retry_after`](Self::retry_after), if any.
403	    #[must_use]
404	    pub fn get_retry_after(&self) -> Option<Duration> {
405	        self.retry_after
406	    }
407	
408	    /// Whether calling again is expected to help without repeating an effect: by default `true` only for
409	    /// `RateLimited` and `Unavailable` (the request was not processed), or after [`retryable(true)`](Self::retryable)
410	    /// for an idempotent operation. True exactly when [`class`](Self::class) is [`ErrorClass::Transient`].
411	    #[must_use]
412	    pub fn is_retryable(&self) -> bool {
413	        self.retryable
414	    }
415	
416	    /// Classify this error for routing: [`ErrorClass::Transient`] when it is retryable, otherwise the code's
417	    /// [`default_class`](ErrorCode::default_class).
418	    #[must_use]
419	    pub fn class(&self) -> ErrorClass {
420	        if self.retryable {
421	            ErrorClass::Transient
422	        } else {
423	            self.code.default_class()
424	        }
425	    }
426	
427	    /// The process exit code to use when this error is fatal. Always `1`.
428	    #[must_use]
429	    pub fn exit_code(&self) -> i32 {
430	        1
431	    }
432	
433	    /// Render in the requested format.
434	    ///
435	    /// [`OutputFormat::Text`] is a TOON 4.4 root object, with no trailing newline: `error: <code label>`, `message: …`
436	    /// (quoted per §7.2), the inline `causes[N]: …` array when there are causes, `exit_code: 1`, then the inline
437	    /// `help[N]: …` array and the `recovery[1]{tool,params,reason}:` table when present.
438	    ///
439	    /// [`OutputFormat::Json`] is a compact JSON object, the `structured_content` companion of the text. Keys:
440	    /// `isError`, `error`, `message`, `causes`, `retryable`, `hints`, `recovery`. `causes` and `hints` are always
441	    /// present, as `[]` when empty; `recovery` is the hint object, or `null`. The shape differs from
442	    /// `AgentResponse`'s JSON (`{body, hints, recovery, isError}`, with `recovery` an array); only `isError` and
443	    /// `hints` mean the same in both.
444	    #[must_use]
445	    pub fn render(&self, format: OutputFormat) -> String {
446	        match format {
447	            OutputFormat::Text => self.render_text(),
448	            OutputFormat::Json => self.render_json(),
449	        }
450	    }
451	
452	    fn render_text(&self) -> String {
453	        let causes_est: usize = self.causes.iter().map(|c| c.len() + 3).sum();
454	        let mut out = String::with_capacity(96 + self.message.len() + causes_est + self.hints.len() * 50);
455	        push_error_fields(&mut out, self.code.label(), &self.message, &self.causes);
456	        crate::hints::append_hints(&mut out, &self.hints);
457	        if let Some(r) = &self.recovery {
458	            crate::recovery::append_recovery(&mut out, std::slice::from_ref(r));
459	        }
460	        out
461	    }
462	
463	    /// Render formatted for GitHub Actions workflow annotations (`::error title=code::message`).
464	    ///
465	    /// The message is encoded as GitHub workflow command data: `%` becomes `%25` first, then CR and LF become `%0D`
466	    /// and `%0A`, so the annotation stays on one line and a literal `%0A` in the message cannot decode to a line
467	    /// break. The `title` property is encoded the same way plus `:` → `%3A` and `,` → `%2C`.
468	    #[must_use]
469	    pub fn render_github_annotation(&self) -> String {
470	        format!(
471	            "::error title={}::{}",
472	            escape_annotation_property(self.code.label()),
473	            escape_annotation_data(&self.message)
474	        )
475	    }
476	
477	    fn render_json(&self) -> String {
478	        let hints_est: usize = self.hints.iter().map(|h| h.as_str().len() + 4).sum();
479	        let causes_est: usize = self.causes.iter().map(|c| c.len() + 4).sum();
480	        let recovery_est: usize = self.recovery.as_ref().map_or(0, |r| {
481	            50 + r.tool.len()
482	                + r.params.iter().map(|_| 20usize).sum::<usize>()
483	                + r.reason.as_ref().map_or(0, |s| s.len() + 12)
484	        });
485	        let mut out = String::with_capacity(140 + self.message.len() + causes_est + hints_est + recovery_est);
486	        out.push_str("{\"isError\":true,\"error\":");
487	        crate::json::push_str(&mut out, self.code.label());
488	        out.push_str(",\"message\":");
489	        crate::json::push_str(&mut out, &self.message);
490	        out.push_str(",\"causes\":");
491	        crate::json::push_str_array(&mut out, self.causes.iter().map(String::as_str));
492	        out.push_str(",\"retryable\":");
493	        crate::json::push_bool(&mut out, self.retryable);
494	        out.push_str(",\"hints\":");
495	        crate::json::push_str_array(&mut out, self.hints.iter().map(Hint::as_str));
496	        out.push_str(",\"recovery\":");
497	        match &self.recovery {
498	            None => out.push_str("null"),
499	            Some(r) => crate::json::push_recovery(&mut out, r),
500	        }
501	        out.push('}');
502	        out
503	    }
504	
505	    /// Build an MCP [`CallToolResult`](crate::mcp::CallToolResult) representing this error.
506	    ///
507	    /// Sets `is_error: true`. Text content is `render(OutputFormat::Text)`; `structured_content` is
508	    /// `render(OutputFormat::Json)`.
509	    ///
510	    /// **Canonical path:** call this directly when you hold a `DomainError`.
511	    /// Do not wrap in `AgentResponse::as_error()` — that loses typed fields.
512	    #[must_use]
513	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
514	        crate::mcp::CallToolResult::new(
515	            vec![crate::mcp::ContentBlock::new(self.render_text(), vec![crate::audience::Audience::Assistant])],
516	            true,
517	            Some(crate::mcp::JsonObject::from_trusted(self.render_json())),
518	        )
519	    }
520	}
521	
522	/// The wire form of [`DomainError`]: the object `render(OutputFormat::Json)` writes.
523	#[cfg(feature = "serde")]
524	#[derive(serde::Serialize)]
525	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
526	#[cfg_attr(feature = "schemars", schemars(rename = "DomainError"))]
527	#[serde(rename_all = "camelCase")]
528	struct DomainErrorWire {
529	    /// Always `true`.
530	    #[cfg_attr(feature = "schemars", schemars(schema_with = "const_true_schema"))]
531	    is_error: bool,
532	    /// The snake_case error code label.
533	    #[cfg_attr(feature = "schemars", schemars(with = "ErrorCode"))]
534	    error: &'static str,
535	    /// Human-readable message.
536	    message: String,
537	    /// Why it happened, outermost first; `[]` when unknown.
538	    causes: Vec<String>,
539	    /// Whether calling again is expected to help without repeating an effect.
540	    retryable: bool,
541	    /// Contextual hints.
542	    hints: Vec<String>,
543	    /// The structured recovery hint, or `null`.
544	    recovery: Option<RecoveryHint>,
545	}
546	
547	#[cfg(feature = "schemars")]
548	fn const_true_schema(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
549	    schemars::json_schema!({ "type": "boolean", "const": true })
550	}
551	
552	#[cfg(feature = "serde")]
553	impl From<DomainError> for DomainErrorWire {
554	    fn from(e: DomainError) -> Self {
555	        Self {
556	            is_error: true,
557	            error: e.code.label(),
558	            message: e.message,
559	            causes: e.causes,
560	            retryable: e.retryable,
561	            hints: e.hints.iter().map(|h| h.as_str().to_string()).collect(),
562	            recovery: e.recovery,
563	        }
564	    }
565	}
566	
567	// The schema describes the JSON render/serde wire form above, not the Rust field layout.
568	#[cfg(feature = "schemars")]
569	#[cfg_attr(docsrs, doc(cfg(feature = "schemars")))]
570	impl schemars::JsonSchema for DomainError {
571	    fn schema_name() -> std::borrow::Cow<'static, str> {
572	        DomainErrorWire::schema_name()
573	    }
574	
575	    fn schema_id() -> std::borrow::Cow<'static, str> {
576	        DomainErrorWire::schema_id()
577	    }
578	
579	    fn json_schema(generator: &mut schemars::SchemaGenerator) -> schemars::Schema {
580	        DomainErrorWire::json_schema(generator)
581	    }
582	}
583	
584	impl std::fmt::Display for DomainError {
585	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
586	        write!(f, "{}: {}", self.code.label(), self.message)
587	    }
588	}
589	
590	/// `source()` is always `None`: [`DomainError::from_error_with_causes`] keeps a chain as text in `causes`, not as a stored error.
591	impl std::error::Error for DomainError {}
592	
593	/// The most `source()` links [`DomainError::from_error_with_causes`] walks, so a cyclic chain cannot loop forever.
594	const MAX_CAUSE_LINKS: usize = 128;
595	
596	/// Encode GitHub workflow command data (the message): `%` first, so an encoded sequence in the input stays literal,
597	/// then CR and LF.
598	fn escape_annotation_data(s: &str) -> String {
599	    let mut out = String::with_capacity(s.len() + 8);
600	    for ch in s.chars() {
601	        match ch {
602	            '%' => out.push_str("%25"),
603	            '\r' => out.push_str("%0D"),
604	            '\n' => out.push_str("%0A"),
605	            other => out.push(other),
606	        }
607	    }
608	    out
609	}
610	
611	/// Encode a GitHub workflow command property value: the data encoding plus `:` and `,`, which delimit properties.
612	fn escape_annotation_property(s: &str) -> String {
613	    let mut out = String::with_capacity(s.len() + 8);
614	    for ch in s.chars() {
615	        match ch {
616	            '%' => out.push_str("%25"),
617	            '\r' => out.push_str("%0D"),
618	            '\n' => out.push_str("%0A"),
619	            ':' => out.push_str("%3A"),
620	            ',' => out.push_str("%2C"),
621	            other => out.push(other),
622	        }
623	    }
624	    out
625	}
626	
627	/// The fields every rendered error document starts with: `error: <code>`, `message: …`, `causes[N]: …` (only when
628	/// there are causes), `exit_code: 1`.
629	fn push_error_fields(out: &mut String, code: &str, message: &str, causes: &[String]) {
630	    out.push_str("error: ");
631	    out.push_str(code);
632	    out.push_str("\nmessage: ");
633	    out.push_str(&crate::toon::escape_value(message));
634	    crate::hints::append_inline_strings(out, "causes", causes.iter().map(String::as_str));
635	    out.push_str("\nexit_code: 1");
636	}
