90	/// than retrying from scratch. Every entry carries its `index` in the caller's op slice, so the rendered report
91	/// keeps `results[i]` and `ops[i]` aligned.
92	///
93	/// For a fully-completed prior call, see [`crate::resilience::AlreadyDone`]
94	/// and [`crate::resilience::already_done`].
95	///
96	/// Build it with [`PartialSuccess::try_new`] (or [`PartialSuccess::default`] for an empty batch) and read it with the
97	/// getters. Each index has exactly one outcome: the fields are private, so a report that lists an operation as both
98	/// completed and failed cannot be built.
99	///
100	/// ```compile_fail,E0616
101	/// let mut ps = michi_core::PartialSuccess::default();
102	/// ps.completed.push(michi_core::CompletedOp::new(0, "a"));
103	/// ```
104	#[derive(Debug, Clone, Default, PartialEq)]
105	#[non_exhaustive]
106	pub struct PartialSuccess {
107	    completed: Vec<CompletedOp>,
108	    failed: Vec<FailedOp>,
109	    skipped: Vec<SkippedOp>,
110	}
