113	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
114	#[non_exhaustive]
115	pub struct DuplicateOpIndex {
116	    /// The index that appeared more than once across `completed`, `failed` and `skipped`.
117	    pub index: usize,
118	}
