120	impl std::fmt::Display for DuplicateOpIndex {
121	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
122	        write!(f, "operation index {} has more than one outcome", self.index)
123	    }
124	}
