128	impl PartialSuccess {
129	    /// A partial-success report from the completed, failed and skipped operations, each kept in the order given.
130	    ///
131	    /// # Errors
132	    ///
133	    /// [`DuplicateOpIndex`] naming the first index (in completed, failed, skipped order) that appears more than once,
134	    /// within one list or across them.
135	    pub fn try_new(
136	        completed: Vec<CompletedOp>,
137	        failed: Vec<FailedOp>,
138	        skipped: Vec<SkippedOp>,
139	    ) -> Result<Self, DuplicateOpIndex> {
140	        let indices = completed
141	            .iter()
142	            .map(|c| c.index)
143	            .chain(failed.iter().map(|f| f.index))
144	            .chain(skipped.iter().map(|s| s.index));
145	        let mut seen = std::collections::HashSet::with_capacity(completed.len() + failed.len() + skipped.len());
146	        for index in indices {
147	            if !seen.insert(index) {
148	                return Err(DuplicateOpIndex { index });
149	            }
150	        }
151	        Ok(Self { completed, failed, skipped })
152	    }
