172	    /// Render as a TOON 4.4 root object, with no trailing newline: a quoted summary, one tabular array per non-empty
173	    /// outcome category, then the failed operations' recovery hints as a `recovery[N]{tool,params,reason}:` table
174	    /// (see [`crate::recovery::render_recovery`]).
175	    ///
176	    /// Format:
177	    /// ```text
178	    /// partial_success: "2 completed, 1 failed, 1 skipped"
179	    /// completed[2]{index,operation}:
180	    ///   0,create_issue
181	    ///   1,add_label
182	    /// failed[1]{index,operation,reason}:
183	    ///   2,assign_user,User 'ghost' not found
184	    /// skipped[1]{index,operation,reason}:
185	    ///   3,notify_team,budget_exhausted
186	    /// recovery[1]{tool,params,reason}:
187	    ///   assign_user,"{\"user\":\"alice\"}",null
188	    /// ```
189	    ///
190	    /// Rows keep the order of the vectors, and `index` is written as given (never renumbered). Every string is quoted
191	    /// per §7.2; a skipped step with no reason renders `null` in the `reason` column. Empty categories are omitted.
192	    #[must_use]
193	    pub fn render(&self) -> String {
194	        let mut out = String::with_capacity(
195	            64 + self.completed.iter().map(|s| s.operation.len() + 24).sum::<usize>()
196	                + self.failed.iter().map(|f| f.operation.len() + f.reason.len() + 80).sum::<usize>()
197	                + self
198	                    .skipped
199	                    .iter()
200	                    .map(|s| s.operation.len() + s.reason.as_ref().map_or(4, String::len) + 24)
201	                    .sum::<usize>(),
202	        );
203	        let _ = write!(
204	            out,
205	            "partial_success: \"{} completed, {} failed, {} skipped\"",
206	            self.completed.len(),
207	            self.failed.len(),
208	            self.skipped.len()
209	        );
210	
211	        if !self.completed.is_empty() {
212	            table::push_header(&mut out, "completed", self.completed.len(), ["index", "operation"]);
213	            for c in &self.completed {
214	                table::push_row(&mut out, &[Cell::count(c.index), Cell::Str(&c.operation)]);
215	            }
216	        }
217	
218	        if !self.failed.is_empty() {
219	            table::push_header(&mut out, "failed", self.failed.len(), ["index", "operation", "reason"]);
220	            for f in &self.failed {
221	                table::push_row(&mut out, &[Cell::count(f.index), Cell::Str(&f.operation), Cell::Str(&f.reason)]);
222	            }
223	        }
224	
225	        if !self.skipped.is_empty() {
226	            table::push_header(&mut out, "skipped", self.skipped.len(), ["index", "operation", "reason"]);
227	            for s in &self.skipped {
228	                let cells = [Cell::count(s.index), Cell::Str(&s.operation), Cell::opt_str(s.reason.as_deref())];
229	                table::push_row(&mut out, &cells);
230	            }
231	        }
232	
233	        let recovery_hints: Vec<crate::recovery::RecoveryHint> =
234	            self.failed.iter().filter_map(|f| f.recovery.clone()).collect();
235	        crate::recovery::append_recovery(&mut out, &recovery_hints);
236	
237	        out
238	    }
