4	/// Health classification for an individual status item.
5	#[derive(Debug, Clone, PartialEq, Eq)]
6	#[non_exhaustive]
7	pub enum Health {
8	    /// Operating normally — renders health `ok` and reason `null`.
9	    Ok,
10	    /// Degraded but still serving; carries a short reason. Renders health `degraded`.
11	    Degraded(String),
12	    /// Not serving; carries a short reason. Renders health `error`.
13	    Error(String),
14	}
15	
16	/// A single named component with a value and optional health signal.
17	///
18	/// `#[non_exhaustive]`: build it with [`StatusItem::new`] (and [`StatusItem::health`]); the fields stay public.
19	#[derive(Debug, Clone, PartialEq)]
20	#[non_exhaustive]
21	pub struct StatusItem {
22	    /// Component key, e.g. `"index"`, `"cache"`.
23	    pub key: String,
24	    /// The component's actual value.
25	    pub value: KvValue,
26	    /// Optional health signal; `None` renders health and reason as `null`.
27	    pub health: Option<Health>,
28	}
29	
30	impl StatusItem {
31	    /// A status item with no health signal.
32	    #[must_use]
33	    pub fn new(key: impl Into<String>, value: KvValue) -> Self {
34	        Self { key: key.into(), value, health: None }
35	    }
36	
37	    /// Attach a health signal.
38	    #[must_use]
39	    pub fn health(mut self, health: Health) -> Self {
40	        self.health = Some(health);
41	        self
42	    }
43	}
44	
45	/// Content-first orientation response (AXI **P8**).
46	#[derive(Debug, Clone, PartialEq)]
47	#[non_exhaustive]
48	pub struct StatusResponse {
49	    /// The tool's name, shown as the first line.
50	    pub tool_name: String,
51	    /// One-line description, shown as the second line.
52	    pub description: String,
53	    /// Component statuses.
54	    pub items: Vec<StatusItem>,
55	    /// Optional contextual hints for the agent.
56	    pub hints: Vec<Hint>,
57	}
58	
59	impl StatusResponse {
60	    /// Create a status response.
61	    pub fn new(tool_name: impl Into<String>, description: impl Into<String>, items: Vec<StatusItem>) -> Self {
62	        Self { tool_name: tool_name.into(), description: description.into(), items, hints: Vec::new() }
63	    }
64	
65	    /// Replace the contextual hints with `hints`.
66	    #[must_use]
67	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
68	        self.hints = hints;
69	        self
70	    }
71	
72	    /// Render this status response as a TOON 4.4 document, with no trailing newline:
73	    ///
74	    /// ```text
75	    /// tool: my-tool
76	    /// description: does things
77	    /// items[2]{key,value,health,reason}:
78	    ///   index,ready,ok,null
79	    ///   cache,warm,degraded,near limit
80	    /// help[1]: Call get_status for detail
81	    /// ```
82	    ///
83	    /// `items` is a tabular array (§9.3), `items: []` when there are none. `health` is `ok`, `degraded`, `error`, or
84	    /// `null` when the item carries no health signal; `reason` is the degraded/error reason, `null` otherwise. Item
85	    /// keys are cells, not root keys, so any key — even a repeated one — keeps the document valid. Every string is
86	    /// quoted per §7.2 and the value is a TOON primitive (see [`KvValue`]).
87	    #[must_use]
88	    pub fn render(&self) -> String {
89	        let capacity = 48
90	            + self.tool_name.len()
91	            + self.description.len()
92	            + self.items.iter().map(|i| i.key.len() + 32).sum::<usize>()
93	            + self.hints.len() * 50;
94	        let mut out = String::with_capacity(capacity);
95	        out.push_str("tool: ");
96	        out.push_str(&crate::toon::escape_value(&self.tool_name));
97	        out.push_str("\ndescription: ");
98	        out.push_str(&crate::toon::escape_value(&self.description));
99	        if self.items.is_empty() {
100	            out.push_str("\nitems: []");
101	        } else {
102	            out.push_str("\nitems[");
103	            out.push_str(&self.items.len().to_string());
104	            out.push_str("]{key,value,health,reason}:");
105	            for item in &self.items {
106	                out.push_str("\n  ");
107	                out.push_str(&crate::toon::escape_value(&item.key));
108	                out.push(',');
109	                crate::kv::push_kv_value(&mut out, &item.value);
110	                let (health, reason) = match &item.health {
111	                    None => ("null", None),
112	                    Some(Health::Ok) => ("ok", None),
113	                    Some(Health::Degraded(reason)) => ("degraded", Some(reason)),
114	                    Some(Health::Error(reason)) => ("error", Some(reason)),
