1	use std::fmt::Write as _;
2	
3	/// Status of an individual pipeline step.
4	///
5	/// Each terminal status maps to one recovery action an agent can take; see "Status model" in
6	/// `docs/spec/08-pipeline-execution.md`.
7	/// Only [`StepStatus::Completed`] and [`StepStatus::CompletedEarlier`] count as success.
8	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
9	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
10	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
11	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
12	#[non_exhaustive]
13	pub enum StepStatus {
14	    /// Not started yet.
15	    Pending,
16	    /// In flight. A finished run never reports it; it appears in records persisted while a run was in progress.
17	    Running,
18	    /// Ran and succeeded in this run.
19	    Completed,
20	    /// Its effect was already in place, so it was not run: it succeeded earlier in the same run (carried over by
21	    /// resume), the caller verified it as applied, or its precheck found the effect already applied.
22	    CompletedEarlier,
23	    /// Failed definitively, or with an error that is safe to replay. Also covers a step that was never started
24	    /// because its deadline group's window had closed (michi-pipeline's `DeadlinePassed`).
25	    Failed,
26	    /// Ran, but whether it took effect is unknown. Verify before running it again.
27	    OutcomeUnknown(UnknownCause),
28	    /// Never took effect, for the given reason.
29	    Skipped(SkipReason),
30	    /// Never invoked, for the given reason.
31	    NotRun(NotRunReason),
32	    /// The step's own code panicked: a harness failure, distinct from an error the step returned.
33	    Panicked,
34	}
35	
36	/// Why a step was skipped.
37	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
38	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
39	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
40	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
41	#[non_exhaustive]
42	pub enum SkipReason {
43	    /// A prerequisite did not complete.
44	    PrerequisiteFailed,
45	    /// The run was cancelled before this step took effect.
46	    Cancelled,
47	}
48	
49	/// Why a step was never invoked.
50	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
51	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
52	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
53	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
54	#[non_exhaustive]
55	pub enum NotRunReason {
56	    /// Its circuit breaker was open.
57	    CircuitOpen,
58	    /// Its precheck could not tell whether its effect was already in place, so it was not run. Rendered
59	    /// `unverified`.
60	    Unverified,
61	    /// Its start could not be recorded durably, so it was not run. Rendered `start_not_recorded`.
62	    StartNotRecorded,
63	}
64	
65	/// Why a step's outcome is unknown.
66	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
67	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
68	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
69	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
70	#[non_exhaustive]
71	pub enum UnknownCause {
72	    /// An attempt timed out.
73	    Timeout,
74	    /// A gateway reported HTTP 502 or 504.
75	    Gateway,
76	    /// The run was cancelled while the step was in flight and the attempt was dropped.
77	    Cancelled,
78	    /// The step was in flight when the process running it stopped.
79	    Interrupted,
80	    /// The step failed with an error that does not say whether its effect landed (an HTTP 500, say). Rendered
81	    /// `step_failed`.
82	    StepFailed,
83	}
84	
85	impl StepStatus {
86	    /// The snake_case status label used in rendered output, without its reason.
