111	pub enum ToonError {
112	    InvalidTypeName { name: String },
113	    InvalidFieldName { name: String },
114	    RowLengthMismatch { row_index: usize, expected: usize, actual: usize },
115	    InvalidItem { row_index: usize, reason: String },
116	    TooManyFields { count: usize, max: usize },
