10	/// MCP content-block annotations (JavaScript-friendly). Currently carries
11	/// only `audience` — michi has no concept of MCP's optional `priority`.
12	#[napi(object, js_name = "Annotations")]
13	#[derive(Debug, Clone)]
14	pub struct JsAnnotations {
15	    /// `["assistant"]` or `["user"]` — which surface(s) this block targets.
16	    pub audience: Vec<String>,
17	}
18	
19	/// One MCP content block (JavaScript-friendly). Wire-conformant with MCP's
20	/// text content shape: `{type: "text", text, annotations: {audience: [...]}}`.
21	#[napi(object, js_name = "ContentBlock")]
22	#[derive(Debug, Clone)]
23	pub struct JsContentBlock {
24	    /// Always `"text"` — michi only ever produces text content blocks.
25	    #[napi(js_name = "type")]
26	    pub content_type: String,
27	    /// The block's text content.
28	    pub text: String,
29	    /// Which surface(s) this block is meant for.
30	    pub annotations: JsAnnotations,
31	}
32	
33	/// The MCP `CallToolResult` shape, returned by `AgentResponse.toCallToolResult`.
34	#[napi(object, js_name = "CallToolResult")]
35	#[derive(Debug, Clone)]
36	pub struct JsCallToolResult {
37	    /// Text content blocks.
38	    pub content: Vec<JsContentBlock>,
39	    /// Whether this is a tool execution error.
40	    #[napi(js_name = "isError")]
41	    pub is_error: bool,
42	    /// The JSON companion to `content[0]` (the `renderJson()` object), as a
43	    /// real parsed JSON value — not a string the caller has to `JSON.parse()`
44	    /// themselves.
45	    #[napi(js_name = "structuredContent")]
46	    pub structured_content: serde_json::Value,
47	}
48	
49	/// Bytes charged to a response's total for each section beyond its strings: roughly the size of the `Section` itself.
50	const SECTION_OVERHEAD: usize = 64;
51	
52	/// String bytes one [`JsAgentResponse`] holds, per slot. A slot that a call replaces (`truncationHint`,
53	/// `humanContent`) gives its old bytes back; `items`, `kvItems`, `hint` and `recoveryHint` each add a block, so they
54	/// only add.
55	#[derive(Debug, Default)]
56	struct HeldBytes {
57	    type_name: usize,
58	    items: usize,
59	    kv_items: usize,
60	    hints: usize,
61	    recovery: usize,
62	    truncation_hint: usize,
63	    human_content: usize,
64	}
65	
66	impl HeldBytes {
67	    fn total(&self) -> usize {
68	        [self.type_name, self.items, self.kv_items, self.hints, self.recovery, self.truncation_hint, self.human_content]
69	            .iter()
70	            .fold(0, |acc, n| acc.saturating_add(*n))
71	    }
72	
73	    /// An error if replacing a slot holding `old` bytes with `new` would take the total past
74	    /// [`input::MAX_INPUT_BYTES`]. Changes nothing: the caller stores the new slot size once its call succeeds.
75	    fn check_replace(&self, old: usize, new: usize) -> napi::Result<()> {
76	        let total = self.total().saturating_sub(old).saturating_add(new);
77	        if total > input::MAX_INPUT_BYTES {
78	            return Err(napi::Error::from_reason(format!(
79	                "cumulative byte total {total} exceeds maximum of {}",
80	                input::MAX_INPUT_BYTES
81	            )));
82	        }
83	        Ok(())
84	    }
85	}
86	
87	/// What one row costs beyond its cells: the row vector. `Array(100000).fill([])` has no cells and still keeps
88	/// 100,000 of these.
89	const ROW_OVERHEAD: usize = std::mem::size_of::<Vec<crate::toon::Value>>();
90	
91	/// What one field name costs: its string and the `String` that holds it.
92	fn field_cost(f: &str) -> usize {
93	    std::mem::size_of::<String>().saturating_add(f.len())
94	}
95	
96	/// NAPI wrapper around [`crate::response::AgentResponse`].
97	///
98	/// Besides each call's own limits, one object holds at most 16 MiB across all its calls: caller strings (type name,
99	/// fields, cells, keys, hints, recovery hints, truncation hint and human content) plus the storage rows and cells
100	/// keep, so a table of empty rows, numbers or nulls is charged too. A call that would pass that total
101	/// is rejected and leaves the builder unchanged; replacing `truncationHint` or `humanContent` gives the old value's
102	/// bytes back first. Every `items` and `kvItems` call adds a section, so their bytes add up; each section is also
103	/// charged the type name's bytes plus 64, so empty calls are not free.
104	///
105	/// The total bounds the output too: a render is at most 19 times the bytes held (control characters, which escape to
106	/// six bytes in the text and again in the JSON, are the worst case), under V8's string limit; see
107	/// [`input::MAX_INPUT_BYTES`].
108	///
109	/// Both methods name their section for the type name, and a section is a root key in the rendered document. Two
110	/// `items` calls, or a `kvItems` key equal to the type name, therefore render the `toon_validation_failed` error
111	/// (`isError` true) instead of invalid TOON. The JS surface renders one list per response.
112	#[napi(js_name = "AgentResponse")]
113	#[derive(Debug)]
114	pub struct JsAgentResponse {
115	    inner: Option<crate::response::AgentResponse>,
116	    /// The type name, which names the sections `items` and `kvItems` append.
117	    name: String,
118	    /// Cumulative count of [`Self::hint`] calls, capped at [`MAX_HINTS`].
119	    hint_count: usize,
120	    /// Cumulative count of [`Self::recovery_hint`] calls, capped at [`MAX_HINTS`].
121	    recovery_count: usize,
122	    /// String bytes held, capped at [`input::MAX_INPUT_BYTES`] in all.
123	    held: HeldBytes,
124	}
125	
126	impl JsAgentResponse {
127	    /// What every section costs before its own strings: a copy of the type name, which names it, plus a fixed
128	    /// allowance for the section itself. Without it an empty `items` or `kvItems` call would be free, and a loop of
129	    /// them would grow the response past the cap.
130	    fn section_cost(&self) -> usize {
131	        self.name.len().saturating_add(SECTION_OVERHEAD)
132	    }
133	
134	    fn take(&mut self) -> napi::Result<crate::response::AgentResponse> {
135	        self.inner.take().ok_or_else(consumed)
136	    }
137	
138	    fn built(&self) -> napi::Result<&crate::response::AgentResponse> {
139	        self.inner.as_ref().ok_or_else(consumed)
140	    }
141	
142	    /// Append a TOON list section. The caller has bounded `rows`, `fields` and every row's length (see
143	    /// [`Self::items`]); this charges the bytes they keep, then converts, so the builder is unchanged on error.
144	    fn add_items(
145	        &mut self,
146	        rows: Vec<Vec<JsToonValue>>,
147	        fields: Vec<String>,
148	        total_count: Option<JsCount>,
149	    ) -> napi::Result<()> {
150	        let bytes = fields
151	            .iter()
152	            .map(|f| field_cost(f.as_str()))
153	            .chain(rows.iter().map(|row| row.iter().map(cell_cost).fold(ROW_OVERHEAD, usize::saturating_add)))
154	            .fold(self.section_cost(), usize::saturating_add);
155	        self.held.check_replace(0, bytes)?;
156	        let converted: Vec<Vec<crate::toon::Value>> = rows
157	            .into_iter()
158	            .map(|row| row.into_iter().map(|v| Ok(v.into_cell()?.into())).collect::<napi::Result<Vec<_>>>())
159	            .collect::<napi::Result<Vec<_>>>()?;
160	        let b = self.take()?;
161	        let section = crate::section::Section::toon(self.name.clone(), fields, converted)
162	            .total_count(total_count.map(JsCount::get));
163	        self.inner = Some(b.section(section));
164	        self.held.items = self.held.items.saturating_add(bytes);
165	        Ok(())
166	    }
167	
168	    /// Append a KV section: the same accounting as [`Self::add_items`].
169	    fn add_kv_items(&mut self, items: Vec<JsKvItem>, total_count: Option<JsCount>) -> napi::Result<()> {
170	        let bytes = items
171	            .iter()
172	            .map(|i| std::mem::size_of::<String>().saturating_add(i.key.len()).saturating_add(cell_cost(&i.value)))
173	            .fold(self.section_cost(), usize::saturating_add);
174	        self.held.check_replace(0, bytes)?;
175	        let converted = items
176	            .into_iter()
177	            .map(|i| Ok(crate::kv::KvItem::new(i.key, i.value.into_cell()?.into())))
178	            .collect::<napi::Result<Vec<_>>>()?;
179	        let b = self.take()?;
180	        let section =
181	            crate::section::Section::kv(self.name.clone(), converted).total_count(total_count.map(JsCount::get));
182	        self.inner = Some(b.section(section));
183	        self.held.kv_items = self.held.kv_items.saturating_add(bytes);
184	        Ok(())
185	    }
186	}
187	
188	fn consumed() -> napi::Error {
189	    napi::Error::from_reason("AgentResponse already consumed")
190	}
191	
192	#[napi]
193	impl JsAgentResponse {
194	    /// Create a new response builder for the given type name, `new AgentResponse(typeName)`.
195	    ///
196	    /// # Errors
197	    ///
198	    /// Rejects a `typeName` over 4 KiB.
199	    #[napi(constructor, catch_unwind)]
200	    pub fn new(type_name: String) -> napi::Result<Self> {
201	        input::check_bytes("typeName", &type_name, MAX_NAME_BYTES)?;
202	        let held = HeldBytes { type_name: type_name.len(), ..HeldBytes::default() };
203	        let inner = Some(crate::response::AgentResponse::new(type_name.clone()));
204	        Ok(Self { inner, name: type_name, hint_count: 0, recovery_count: 0, held })
205	    }
206	
207	    /// Append a TOON list section named for the response's type. Every call adds a section, rendered in call order;
208	    /// a second `items` call repeats the root key and renders the validation error (see the type docs).
209	    /// `totalCount`, when given, is how many rows existed before any cut; `totalCount: n` renders only when `n` is
210	    /// larger than the rows passed.
211	    ///
212	    /// # Errors
213	    ///
214	    /// Rejects, before converting anything, more than 100,000 rows, 1,000 fields or 1,000 values in a row, and
215	    /// more than 1,000,000 cells in all; while converting, a field name over 4 KiB, a cell over 1 MiB, more than
216	    /// 16 MiB of strings in the call, or an invalid cell; a `totalCount` that is not a finite, non-negative integer;
217	    /// then strings that would take the response past its 16 MiB total. The builder is unchanged on error.
218	    #[napi(
219	        ts_args_type = "rows: Array<Array<ToonValue>>, fields: Array<string>, totalCount?: number | null",
220	        catch_unwind
221	    )]
222	    pub fn items(&mut self, rows: Unknown<'_>, fields: Unknown<'_>, total_count: Option<JsCount>) -> napi::Result<()> {
223	        let mut budget = Budget::new();
224	        let rows = List::new(rows, "rows")?;
225	        let fields = List::new(fields, "fields")?;
226	        input::check_len("rows", rows.len(), MAX_ROWS)?;
227	        input::check_len("fields", fields.len(), MAX_FIELDS)?;
228	        let fields = budget.strings(&fields, "fields", MAX_FIELDS, "field name", MAX_NAME_BYTES)?;
229	        let rows = budget.rows(&rows, MAX_ROWS, MAX_FIELDS, "maximum")?;
230	        self.add_items(rows, fields, total_count)
231	    }
232	
233	    /// Append a KV section named for the response's type; the name is not printed. Every call adds a section,
234	    /// rendered in call order. `totalCount` works as in [`Self::items`].
235	    ///
236	    /// # Errors
237	    ///
238	    /// Rejects more than 1,000 items before converting any, a key over 4 KiB, a value over 1 MiB, more than 16 MiB
239	    /// of strings in the call, an invalid value, a `totalCount` that is not a finite, non-negative integer, or
240	    /// strings that would take the response past its 16 MiB total. The builder is unchanged on error.
241	    #[napi(js_name = "kvItems", ts_args_type = "items: Array<KvItem>, totalCount?: number | null", catch_unwind)]
242	    pub fn kv_items(&mut self, items: Unknown<'_>, total_count: Option<JsCount>) -> napi::Result<()> {
243	        let mut budget = Budget::new();
244	        let items = List::new(items, "items")?;
245	        let items = budget.kv_items(&items, MAX_FIELDS)?;
246	        self.add_kv_items(items, total_count)
247	    }
248	
249	    /// Append a contextual hint.
250	    ///
251	    /// # Errors
252	    ///
253	    /// Rejects a hint over 1 MiB, any hint after the 10,000th, and a hint that would take the response past its
254	    /// 16 MiB total.
255	    #[napi(catch_unwind)]
256	    pub fn hint(&mut self, hint: String) -> napi::Result<()> {
257	        if self.hint_count >= MAX_HINTS {
258	            return Err(napi::Error::from_reason(format!("cumulative hint count exceeds maximum of {MAX_HINTS}")));
259	        }
260	        input::check_bytes("hint", &hint, MAX_STRING_BYTES)?;
261	        let bytes = hint.len();
262	        self.held.check_replace(0, bytes)?;
263	        let b = self.take()?;
264	        self.inner = Some(b.hint(hint));
265	        self.hint_count += 1;
266	        self.held.hints = self.held.hints.saturating_add(bytes);
267	        Ok(())
268	    }
269	
270	    /// Append a recovery hint naming a tool.
271	    ///
272	    /// # Errors
273	    ///
274	    /// Rejects a `tool` over 4 KiB, a `reason` over 1 MiB, any recovery hint after the 10,000th, and one that would
275	    /// take the response past its 16 MiB total.
276	    #[napi(catch_unwind)]
277	    pub fn recovery_hint(&mut self, tool: String, reason: Option<String>) -> napi::Result<()> {
278	        if self.recovery_count >= MAX_HINTS {
279	            return Err(napi::Error::from_reason(format!(
280	                "cumulative recovery hint count exceeds maximum of {MAX_HINTS}"
281	            )));
282	        }
283	        input::check_bytes("tool", &tool, MAX_NAME_BYTES)?;
284	        if let Some(reason) = &reason {
285	            input::check_bytes("reason", reason, MAX_STRING_BYTES)?;
286	        }
287	        let bytes = tool.len().saturating_add(reason.as_ref().map_or(0, String::len));
288	        self.held.check_replace(0, bytes)?;
289	        let b = self.take()?;
290	        let mut hint = crate::recovery::RecoveryHint::new(tool);
291	        if let Some(reason) = reason {
292	            hint = hint.reason(reason);
293	        }
294	        self.inner = Some(b.recovery_hint(hint));
295	        self.recovery_count += 1;
296	        self.held.recovery = self.held.recovery.saturating_add(bytes);
297	        Ok(())
298	    }
299	
300	    /// Set the caller's instruction for getting a cut TOON cell in full (e.g. `"full=true"`), delivered in `help[]`
301	    /// after the response's own hints when a cell was cut. Not called: the `truncated` block still reports each cut.
302	    /// Tool-author text, never data.
303	    ///
304	    /// # Errors
305	    ///
306	    /// Rejects a hint over 4 KiB, or one that would take the response past its 16 MiB total. A hint over 256 chars is
307	    /// accepted here but renders as a `toon_validation_failed` error block, like any other options michi-core's TOON
308	    /// validation rejects.
309	    #[napi(catch_unwind)]
310	    pub fn truncation_hint(&mut self, hint: String) -> napi::Result<()> {
311	        input::check_bytes("truncationHint", &hint, MAX_NAME_BYTES)?;
312	        let bytes = hint.len();
313	        self.held.check_replace(self.held.truncation_hint, bytes)?;
314	        let b = self.take()?;
315	        self.inner = Some(b.truncation_hint(hint));
316	        self.held.truncation_hint = bytes;
317	        Ok(())
318	    }
319	
320	    /// Mark this response as an error state.
321	    ///
322	    /// # Errors
323	    ///
324	    /// Returns an error if the builder was already consumed (an internal invariant; should not happen in normal use).
325	    #[napi(catch_unwind)]
326	    pub fn as_error(&mut self) -> napi::Result<()> {
327	        let b = self.take()?;
328	        self.inner = Some(b.as_error());
329	        Ok(())
330	    }
331	
332	    /// Attach a human-facing companion block (`audience: user`) for MCP callers. A second call replaces the first.
333	    ///
334	    /// # Errors
335	    ///
336	    /// Rejects text over 1 MiB, or text that would take the response past its 16 MiB total. The builder is unchanged
337	    /// on error.
338	    #[napi(catch_unwind)]
339	    pub fn human_content(&mut self, text: String) -> napi::Result<()> {
340	        input::check_bytes("humanContent", &text, MAX_STRING_BYTES)?;
341	        let bytes = text.len();
342	        self.held.check_replace(self.held.human_content, bytes)?;
343	        let b = self.take()?;
344	        self.inner = Some(b.human_content(text));
345	        self.held.human_content = bytes;
346	        Ok(())
347	    }
348	
349	    /// Render the response as text: its sections in call order, then `help[]` and `recovery[]`. The one text render;
350	    /// see [`crate::response::AgentResponse::render`].
351	    ///
352	    /// # Errors
353	    ///
354	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
355	    #[napi(catch_unwind)]
356	    pub fn render_text(&self) -> napi::Result<String> {
357	        Ok(self.built()?.render(crate::response::OutputFormat::Text))
358	    }
359	
360	    /// Render as a compact JSON string (`{"body":...,"hints":[...],"recovery":[...],"isError":bool}`).
361	    ///
362	    /// # Errors
363	    ///
364	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
365	    #[napi(catch_unwind)]
366	    pub fn render_json(&self) -> napi::Result<String> {
367	        Ok(self.built()?.render(crate::response::OutputFormat::Json))
368	    }
369	
370	    /// Render just the `help[N]:` block — the three-surface seam for MCP
371	    /// frameworks assembling their own display body separately.
372	    ///
373	    /// # Errors
374	    ///
375	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
376	    #[napi(catch_unwind)]
377	    pub fn render_hints_only(&self) -> napi::Result<String> {
378	        Ok(self.built()?.render_hints_only())
379	    }
380	
381	    /// Render for the given audience — `"assistant"` or `"user"`. `"user"`
382	    /// returns the `humanContent()` block if one was set, falling back to
383	    /// the same agent-oriented rendering `"assistant"` would produce
384	    /// otherwise — never an empty string. See [`Self::has_human_content`]
385	    /// to check for the fallback case ahead of time.
386	    ///
387	    /// # Errors
388	    ///
389	    /// Returns an error if `audience` is anything other than `"assistant"`
390	    /// or `"user"`, or if an internal invariant is violated (should not
391	    /// happen in normal use).
392	    #[napi(catch_unwind)]
393	    #[allow(clippy::needless_pass_by_value)] // napi-derive requires owned String for JS string params
394	    pub fn render_for(&self, audience: String) -> napi::Result<String> {
395	        let audience = match audience.as_str() {
396	            "assistant" => crate::audience::Audience::Assistant,
397	            "user" => crate::audience::Audience::User,
398	            other => {
399	                return Err(napi::Error::from_reason(format!(
400	                    "unknown audience {other:?}: expected \"assistant\" or \"user\""
401	                )))
402	            }
403	        };
404	        Ok(self.built()?.render_for(audience))
405	    }
406	
407	    /// Whether `.humanContent()` was set on this builder.
408	    ///
409	    /// # Errors
410	    ///
411	    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
412	    #[napi(catch_unwind)]
413	    pub fn has_human_content(&self) -> napi::Result<bool> {
414	        Ok(self.built()?.has_human_content())
415	    }
416	
417	    /// Build the MCP `CallToolResult` for this response. Returns a real
418	    /// object, not a JSON string — `structuredContent` is a parsed
419	    /// `serde_json::Value`, so TypeScript callers don't need to
420	    /// `JSON.parse()` it themselves.

