1	//! Generated JSON Schemas must describe what serde actually puts on the wire, checked against real serialized values.
2	#![cfg(all(feature = "serde", feature = "schemars"))]
3	
4	use michi_core::kv::KvValue;
5	use michi_core::{Audience, CallToolResult, ContentBlock, DomainError, ErrorCode, RecoveryHint};
6	use std::collections::BTreeSet;
7	
8	/// Resolve a `$ref` against the root schema's `$defs`, or return the schema itself. Under JSON Schema 2020-12 a
9	/// `$ref` sits next to sibling keywords such as `default`, with no `allOf` wrapper.
10	fn resolve<'a>(root: &'a serde_json::Value, schema: &'a serde_json::Value) -> &'a serde_json::Value {
11	    match schema.get("$ref").and_then(serde_json::Value::as_str) {
12	        Some(r) => {
13	            let name = r.strip_prefix("#/$defs/").unwrap_or_else(|| panic!("ref {r} points into $defs"));
14	            &root["$defs"][name]
15	        }
16	        None => schema,
17	    }
18	}
19	
20	#[test]
21	fn schemas_are_json_schema_2020_12() {
22	    let root = serde_json::to_value(schemars::schema_for!(CallToolResult)).expect("schema serializes");
23	    assert_eq!(root["$schema"], "https://json-schema.org/draft/2020-12/schema");
24	    assert!(root.get("definitions").is_none(), "2020-12 keeps subschemas under $defs: {root:#}");
25	    assert!(root["$defs"].get("ContentBlock").is_some(), "{root:#}");
