167	/// Whether a JSON Schema `type` (one name or a list) admits `value`. `integer` is any number with no fractional part,
168	/// as JSON Schema defines it; `number` is any number.
169	fn type_admits(schema: &serde_json::Value, value: &serde_json::Value) -> bool {
170	    let names: Vec<&str> = match &schema["type"] {
171	        serde_json::Value::String(s) => vec![s.as_str()],
172	        serde_json::Value::Array(a) => a.iter().filter_map(serde_json::Value::as_str).collect(),
173	        _ => panic!("expected a `type` keyword in {schema:#}"),
174	    };
175	    names.iter().any(|name| match (*name, value) {
176	        ("string", serde_json::Value::String(_))
177	        | ("boolean", serde_json::Value::Bool(_))
178	        | ("null", serde_json::Value::Null)
179	        | ("number", serde_json::Value::Number(_))
180	        | ("object", serde_json::Value::Object(_))
181	        | ("array", serde_json::Value::Array(_)) => true,
182	        ("integer", serde_json::Value::Number(n)) => {
183	            n.is_i64() || n.is_u64() || n.as_f64().is_some_and(|f| f.fract() == 0.0)
184	        }
185	        _ => false,
186	    })
187	}
