192	/// The `params` value schema and the deserializer accept the same values at every numeric boundary, except
193	/// [`LOSSY_INTEGERS`].
194	#[test]
195	fn recovery_hint_param_schema_and_deserializer_agree() {
196	    let root = serde_json::to_value(schemars::schema_for!(RecoveryHint)).expect("schema serializes");
197	    let value_schema = &resolve(&root, &root)["properties"]["params"]["additionalProperties"];
198	    for param in [
199	        "0",
200	        "-9223372036854775808",
201	        "9223372036854775807",
202	        "9223372036854775808",
203	        "9223372036854775809",
204	        "18446744073709551615",
205	        "18446744073709551616",
206	        "-9223372036854775809",
207	        "1e19",
208	        "0.1",
209	        "1e-300",
210	        "5e-324",
211	        "-5e-324",
212	        "1.7976931348623157e308",
213	        "\"s\"",
214	        "true",
215	        "null",
216	        "[1]",
217	        "{\"a\":1}",
218	    ] {
219	        let json = format!(r#"{{"tool":"t","params":{{"x":{param}}}}}"#);
220	        let value: serde_json::Value = serde_json::from_str(param).expect("valid JSON");
221	        let parsed = serde_json::from_str::<RecoveryHint>(&json);
222	        // The one deliberate gap: JSON Schema cannot say "an integer past i64 only if it has an exact float form",
223	        // so the schema admits these and says so in its description, while the deserializer rejects them rather than
224	        // rounding (integers keep their exact digits).
225	        if LOSSY_INTEGERS.contains(&param) {
226	            assert!(type_admits(value_schema, &value), "{param}");
227	            assert!(parsed.is_err(), "{param} must be rejected, not rounded: {parsed:?}");
228	            continue;
229	        }
230	        assert_eq!(
231	            type_admits(value_schema, &value),
232	            parsed.is_ok(),
233	            "schema and deserializer disagree on {param}: {parsed:?}\nschema: {value_schema:#}"
234	        );
235	        if let Ok(hint) = parsed {
236	            // Whatever is accepted keeps the value a JSON reader sees, and survives another round trip with it.
237	            let back = serde_json::to_string(&hint).expect("serializes");
238	            let again: RecoveryHint = serde_json::from_str(&back).expect("its own output deserializes");
239	            let again = serde_json::to_value(&again).expect("serializes");
240	            match value.as_f64() {
241	                Some(expected) => {
242	                    let got = again["params"]["x"].as_f64().expect("still a number");
243	                    assert_eq!(got.to_bits(), expected.to_bits(), "{param} came back as {back}");
244	                }
245	                None => assert_eq!(again["params"]["x"], value, "{param} came back as {back}"),
246	            }
247	        }
248	    }
249	}
