327	            max: "255",
328	            below: "-1",
329	            above: "256",
330	            accepts: |n| serde_json::from_str::<KvValue>(&format!(r#"{{"Float":[1.5,{n}]}}"#)).is_ok(),
331	        },
332	        IntCase {
333	            schema: variant(&value, "Int"),
334	            min: i64_min,
335	            max: i64_max,
336	            below: i64_below,
337	            above: i64_above,
338	            accepts: |n| serde_json::from_str::<michi_core::toon::Value>(&format!(r#"{{"Int":{n}}}"#)).is_ok(),
339	        },
340	        IntCase {
341	            schema: variant(&value, "UInt"),
342	            min: "0",
343	            max: "18446744073709551615",
344	            below: "-1",
345	            above: "18446744073709551616",
346	            accepts: |n| serde_json::from_str::<michi_core::toon::Value>(&format!(r#"{{"UInt":{n}}}"#)).is_ok(),
