    /// The decimals setting of [`KvValue::Float`] that never rounds: the float renders with its shortest round-trip
    /// digits, in exponent form when TOON's canonical number form calls for it (`1e-300`). Use it when the value
    /// itself matters more than a fixed precision. It is `u8::MAX`, so a count this large meant the same thing for
    /// every value that 255 places could already hold.
    pub const FULL_PRECISION: u8 = u8::MAX;
}

/// Append a KV value as a TOON 4.4 primitive token (§2, §3, §7.2).
///
/// `Text` is quoted only when §7.2 requires it (line breaks become `\n`/`\r` inside quotes); `Int` and `Bool` are
/// literal; `Float(f, decimals)` is rounded to `decimals` places and the rounded value is written in canonical number
/// form; `Duration` is the string `{secs:.1}s`; `Missing` is `null`.
pub(crate) fn push_kv_value(out: &mut String, value: &KvValue) {
    match value {
        KvValue::Text(s) => out.push_str(&crate::toon::escape_value(s)),
        KvValue::Int(n) => {
            let _ = write!(out, "{n}");
        }
        KvValue::Float(f, decimals) => crate::toon::push_f64(out, round_to_decimals(*f, *decimals)),
        KvValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        KvValue::Duration(d) => {
            let mut secs = String::with_capacity(16);
            let _ = write!(secs, "{:.1}s", d.as_secs_f64());
            out.push_str(&crate::toon::escape_value(&secs));
        }
        KvValue::Missing => out.push_str("null"),
    }
}

/// The decimal places `KvValue::Float` needs to reproduce `f` exactly: the fractional digits of its shortest exact
/// representation (Rust's `Display` for f64, which never uses an exponent), so `1e-7` needs 7 and `2.0` needs 0.
/// Non-finite values need 0. A value needing more than 254 places gets [`KvValue::FULL_PRECISION`], which never
/// rounds. Used where a float arrives without a decimals setting.
#[cfg(any(feature = "serde", feature = "napi"))]
pub(crate) fn exact_decimals(f: f64) -> u8 {
    if !f.is_finite() {
        return 0;
    }
    let places = f.to_string().split_once('.').map_or(0, |(_, frac)| frac.len());
    u8::try_from(places).unwrap_or(KvValue::FULL_PRECISION)
}

/// `f` rounded to `decimals` fractional digits by the correctly rounded decimal formatting of `{f:.decimals}`.
/// Non-finite values, and every value at [`KvValue::FULL_PRECISION`], pass through unchanged.
fn round_to_decimals(f: f64, decimals: u8) -> f64 {
    if !f.is_finite() || decimals == KvValue::FULL_PRECISION {
        return f;
    }
    format!("{f:.*}", usize::from(decimals)).parse().unwrap_or(f)
}

/// Error returned by [`render_kv`] when the items cannot form a valid TOON document.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum KvError {
    /// An item key is a root key michi writes itself (`totalCount`, `help`, `recovery`, `truncated`, `budget`,
    /// `sections`, `provenance`, `error`, `message`, `causes` or `exit_code`). It is rejected whether or not that key
    /// is present in this document, so validity never depends on the data, and caller data never renders as one of
    /// michi's own blocks.
    #[error("key {key:?} is a reserved document key ({})", crate::toon::ReservedRootKeys)]
    ReservedKey {
        /// The offending key.
        key: String,
    },
    /// Two items share a key; a TOON object may not repeat a key (§14.3).
    #[error("key {key:?} appears more than once")]
    DuplicateKey {
        /// The offending key.
        key: String,
    },
}

