         operation: delete\nstatus: already_done\nsummary: done\n\
         recovery[1]{tool,params,reason}:\n  index,\"{}\",null"
    );
    let json: serde_json::Value = serde_json::from_str(&r.render_json().expect("renders")).expect("JSON");
    assert_eq!(
