    const r = new AgentResponse('run')
    r.pipeline('step', [{ id: 'fetch', name: 'Fetch', status: 'completed' }])
    r.status('tool-x', 'does x', [{ key: 'index', value: { type: 'str', strVal: 'ready' }, health: 'ok' }])
