    assert.throws(() => r.status('t', 'd', [{ key: 'k', value: { type: 'null' }, health: 'meh' }]), /unknown health/)
    assert.throws(() => r.alreadyDone('x'.repeat(4097), 's'), /^Error: operation byte length/)
    assert.strictEqual(r.renderText(), before)
  })
